import mongoose, {Schema} from 'mongoose';
import {
  INQUIRY_CATEGORIES,
  type InquiryCategory,
  type InquiryPriority,
  type InquiryStatus
} from '../config/supportInquiry';

// 'system' = automatic reply generated by the inquiry queue.
export type SupportMessageSenderType = 'customer' | 'owner' | 'system';

export interface SupportMessageDocument extends mongoose.Document {
  conversationId: mongoose.Types.ObjectId;
  senderType: SupportMessageSenderType;
  senderName: string;
  body: string;
  createdAt: Date;
  readAt?: Date | null;
  // Inquiry log (customer messages only; null for owner / system messages).
  category?: InquiryCategory | null;
  priority?: InquiryPriority | null;
  inquiryStatus?: InquiryStatus | null;
  /** True when keyword detection raised the priority, not the customer. */
  autoFlagged?: boolean;
  matchedKeywords?: string[];
  answeredAt?: Date | null;
  /** 'reply' = owner replied in chat, 'manual' = owner marked it answered. */
  answeredVia?: 'reply' | 'manual' | null;
}

const SupportMessageSchema = new Schema<SupportMessageDocument>(
  {
    conversationId: {
      type: Schema.Types.ObjectId,
      ref: 'SupportConversation',
      required: true
    },
    senderType: {
      type: String,
      enum: ['customer', 'owner', 'system'],
      required: true
    },
    senderName: {type: String, required: true, trim: true},
    body: {type: String, required: true, trim: true},
    readAt: {type: Date, default: null},
    category: {type: String, enum: [...INQUIRY_CATEGORIES, null], default: null},
    priority: {type: String, enum: ['urgent', 'normal', null], default: null},
    inquiryStatus: {
      type: String,
      enum: ['pending', 'answered', 'customer_closed', null],
      default: null
    },
    autoFlagged: {type: Boolean, default: false},
    matchedKeywords: {type: [String], default: []},
    answeredAt: {type: Date, default: null},
    answeredVia: {type: String, enum: ['reply', 'manual', null], default: null}
  },
  {timestamps: true}
);

SupportMessageSchema.index({conversationId: 1, createdAt: 1});
SupportMessageSchema.index({senderType: 1, inquiryStatus: 1, createdAt: -1});
// Change-check poll (GET /changes).
SupportMessageSchema.index({updatedAt: -1});

export const SupportMessageModel = mongoose.model<SupportMessageDocument>(
  'SupportMessage',
  SupportMessageSchema,
  'supportmessages'
);
